     1	<!--
     2	  AC: @ui-task-board ac-4 — Active Fleet row showing running agent work.
     3	  Shows task title, agent name, elapsed time with pulse indicator,
     4	  and last few lines of output.
     5	-->
     6	<script lang="ts">
     7		import type { AgentStatus } from '$lib/api';
     8		import { Badge } from '$lib/components/ui/badge';
     9		import { formatElapsed } from './board-utils';
    10		import Bot from '@lucide/svelte/icons/bot';
    11		import Activity from '@lucide/svelte/icons/activity';
    12		import Terminal from '@lucide/svelte/icons/terminal';
    13	
    14		let {
    15			status,
    16			outputLines = {},
    17			taskTitles = {}
    18		}: {
    19			status: AgentStatus | null;
    20			outputLines?: Record<string, string[]>;
    21			taskTitles?: Record<string, string>;
    22		} = $props();
    23	
    24		let activeInvocations = $derived(status?.active_invocations ?? []);
    25		let isVisible = $derived(status?.dispatch_enabled && activeInvocations.length > 0);
    26	
    27		// AC: @ui-task-board ac-4 — Resolve agent name from agent_definitions
    28		let agentNameMap = $derived(
    29			Object.fromEntries(
    30				(status?.agent_definitions ?? []).map((a) => [a.id, a.name])
    31			)
    32		);
    33	</script>
    34	
    35	{#if isVisible}
    36		<div class="mb-4" data-testid="active-fleet-row">
    37			<div class="flex items-center gap-2 mb-2">
    38				<Activity class="size-4 text-status-in-progress" />
    39				<h3 class="text-sm font-medium">Active Fleet</h3>
    40				<Badge variant="secondary" class="text-[10px]">{activeInvocations.length} running</Badge>
    41			</div>
    42			<div class="flex gap-3 overflow-x-auto pb-2">
    43				{#each activeInvocations as invocation (invocation.session_id)}
    44					{@const lines = outputLines[invocation.session_id] ?? []}
    45					{@const title = invocation.task_ref ? taskTitles[invocation.task_ref] : undefined}
    46					{@const agentName = agentNameMap[invocation.agent_id] ?? invocation.agent_id}
    47					<div
    48						class="flex-shrink-0 w-72 rounded-lg border bg-card p-3 ds-breathe"
    49						data-testid="fleet-card"
    50					>
    51						<div class="flex items-center gap-2 mb-1.5">
    52							<Bot class="size-4 text-muted-foreground" />
    53							<span class="text-xs font-medium truncate" data-testid="fleet-agent-name">{agentName}</span>
    54						</div>
    55	
    56						{#if invocation.task_ref}
    57							{#if title}
    58								<p class="text-xs text-foreground truncate mb-0.5" data-testid="fleet-task-title">
    59									{title}
    60								</p>
    61								<p class="text-[10px] text-muted-foreground font-mono truncate mb-1">
    62									{invocation.task_ref}
    63								</p>
    64							{:else}
    65								<p class="text-xs text-muted-foreground font-mono truncate mb-1">
    66									{invocation.task_ref}
    67								</p>
    68							{/if}
    69						{/if}
    70	
    71						<div class="flex items-center gap-1.5 text-[10px] text-muted-foreground mb-1.5">
    72							<!-- Pulse indicator -->
    73							<span class="relative flex size-2">
    74								<span
    75									class="absolute inline-flex h-full w-full rounded-full bg-status-in-progress opacity-75 ds-breathe"
    76								></span>
    77								<span class="relative inline-flex size-2 rounded-full bg-status-in-progress"></span>
    78							</span>
    79							<span>{formatElapsed(invocation.elapsed_ms)}</span>
    80						</div>
    81	
    82						<!-- AC: @ui-task-board ac-4 — Last few lines of output -->
    83						{#if lines.length > 0}
    84							<div
    85								class="mt-1.5 rounded bg-muted/50 p-1.5 font-mono text-[10px] leading-tight text-muted-foreground overflow-hidden max-h-14"
    86								aria-live="polite"
    87								aria-label="Agent output for {title ?? agentName}"
    88								data-testid="fleet-output"
    89							>
    90								{#each lines as line}
    91									<div class="truncate">{line}</div>
    92								{/each}
    93							</div>
    94						{:else}
    95							<div
    96								class="mt-1.5 flex items-center gap-1 text-[10px] text-muted-foreground/50"
    97								aria-live="polite"
    98								aria-label="Agent output for {title ?? agentName}"
    99								data-testid="fleet-output-empty"
   100							>
   101								<Terminal class="size-3" />
   102								<span>Awaiting output...</span>
   103							</div>
   104						{/if}
   105					</div>
   106				{/each}
   107			</div>
   108		</div>
   109	{/if}
