     1	/**
     2	 * Connection Store
     3	 *
     4	 * Global WebSocket connection state managed via Svelte runes.
     5	 * Provides reactive connection status and message handling.
     6	 *
     7	 * AC Coverage:
     8	 * - ac-28 (@web-dashboard): Automatic reconnect with exponential backoff
     9	 * - ac-29 (@web-dashboard): Connection lost indicator
    10	 * - ac-30 (@web-dashboard): Sequence deduplication
    11	 * - ac-31 (@web-dashboard): Reset lastSeqProcessed on reconnect
    12	 * - ac-32 (@web-dashboard): Re-subscribe on reconnect
    13	 * - ac-33 (@web-dashboard): Trigger UI updates on events
    14	 * - ac-27 (@multi-directory-daemon): Reconnect with different project
    15	 */
    16	
    17	import { WebSocketManager, type WebSocketManagerOptions } from '../websocket/manager.js';
    18	import type { ConnectionState } from '../websocket/types.js';
    19	
    20	// Global WebSocket manager instance
    21	let manager: WebSocketManager | null = null;
    22	
    23	// Reactive state
    24	let connectionState = $state<ConnectionState>('disconnected');
    25	let connectionLost = $state(false);
    26	
    27	/**
    28	 * Initialize WebSocket connection
    29	 * AC: @web-dashboard ac-28
    30	 * AC: @multi-directory-daemon ac-34 - Supports project path option
    31	 */
    32	export function initConnection(options?: WebSocketManagerOptions | string): void {
    33		if (manager) {
    34			console.warn('[ConnectionStore] Already initialized');
    35			return;
    36		}
    37	
    38		manager = new WebSocketManager(options);
    39	
    40		// AC: @web-dashboard ac-29 - Track connection state
    41		manager.onStateChange((state) => {
    42			connectionState = state;
    43			connectionLost = manager!.isConnectionLost();
    44		});
    45	
    46		manager.connect();
    47	}
    48	
    49	/**
    50	 * Reconnect with a different project
    51	 * AC: @multi-directory-daemon ac-27
    52	 */
    53	export function reconnectWithProject(projectPath: string | null): void {
    54		if (!manager) {
    55			console.warn('[ConnectionStore] Not initialized, cannot reconnect with project');
    56			return;
    57		}
    58	
    59		manager.setProjectPath(projectPath);
    60	}
    61	
    62	/**
    63	 * Get connection state
    64	 * AC: @web-dashboard ac-29
    65	 */
    66	export function getConnectionState(): ConnectionState {
    67		return connectionState;
    68	}
    69	
    70	/**
    71	 * Check if connection is lost (>10s)
    72	 * AC: @web-dashboard ac-29
    73	 */
    74	export function isConnectionLost(): boolean {
    75		return connectionLost;
    76	}
    77	
    78	/**
    79	 * Check if connected
    80	 */
    81	export function isConnected(): boolean {
    82		return manager?.isConnected() ?? false;
    83	}
    84	
    85	/**
    86	 * Subscribe to topics
    87	 * AC: @web-dashboard ac-32
    88	 */
    89	export function subscribe(topics: string[]): void {
    90		if (!manager) {
    91			// No-op during SSR or before initialization
    92			return;
    93		}
    94		manager.subscribe(topics);
    95	}
    96	
    97	/**
    98	 * Unsubscribe from topics
    99	 */
   100	export function unsubscribe(topics: string[]): void {
   101		if (!manager) {
   102			// No-op during SSR or before initialization
   103			return;
   104		}
   105		manager.unsubscribe(topics);
   106	}
   107	
